import { parseCsvLine, CsvError } from "./src/csv.mjs";
class RefErr extends Error {}
function ref(text){
  const fields=[]; let field=""; let state=0; let i=0; const n=text.length;
  while(i<n){
    const c=text[i];
    if(state===2){
      if(c==="\""){ if(text[i+1]==="\""){field+="\""; i+=2; continue;} state=3; i++; continue;}
      field+=c; i++; continue;
    }
    if(state===3){
      if(c===","){fields.push(field); field=""; state=0; i++; continue;}
      if(c==="\n" && i===n-1){ i++; continue;}
      if(c==="\r" && text[i+1]==="\n" && i===n-2){ i+=2; continue;}
      throw new RefErr("after close");
    }
    if(state===0 && c==="\""){state=2;i++;continue;}
    if(c===","){fields.push(field); field=""; state=0; i++; continue;}
    if(c==="\"") throw new RefErr("quote outside");
    if(c==="\n"){ if(i===n-1){ i++; continue;} throw new RefErr("lf"); }
    if(c==="\r"){ if(text[i+1]==="\n" && i===n-2){ i+=2; continue;} throw new RefErr("cr"); }
    field+=c; state=1; i++;
  }
  if(state===2) throw new RefErr("unclosed");
  fields.push(field);
  return fields;
}
function run(f,t){ try { const r=f(t); if(!Array.isArray(r)||r.some(x=>typeof x!=="string")) return "BADTYPE:"+JSON.stringify(r); return "OK:"+JSON.stringify(r);} catch(e){ if(e instanceof CsvError||e instanceof RefErr) return "CSVERR"; return "OTHER:"+e.constructor.name+":"+e.message; } }
const alpha=["a","b",",","\"","\n","\r"," ","\t","\u0000","é","\ud83d","\ude00"];
let seed=12345; function rnd(k){ seed=(seed*1103515245+12345)&0x7fffffff; return seed%k; }
let fails=0, tried=0;
// exhaustive over small alphabet up to length 6
const small=["a",",","\"","\n","\r"];
function* all(len){ if(len===0){yield "";return;} for(const p of all(len-1)) for(const c of small) yield p+c; }
for(let L=0;L<=7;L++) for(const t of all(L)){ tried++; const a=run(parseCsvLine,t), b=run(ref,t); if(a!==b){ fails++; if(fails<15) console.log("MISMATCH", JSON.stringify(t), "impl=",a,"ref=",b);} }
for(let k=0;k<300000;k++){ const L=rnd(20); let t=""; for(let j=0;j<L;j++) t+=alpha[rnd(alpha.length)]; tried++; const a=run(parseCsvLine,t), b=run(ref,t); if(a!==b){ fails++; if(fails<30) console.log("MISMATCH", JSON.stringify(t), "impl=",a,"ref=",b);} }
console.log("tried",tried,"mismatches",fails);
'

